		 << s1.getDay() << ' '
		 << s1.getYear() << '\n';
	 print(std::cout, s1);
	 std::cout << '\n';
	 print(std::cout, s2);
	 std::cout << '\n';
	 print(std::cout, s3);
	 std::cout << '\n';
	 print(std::cout, s4);
